(int, int) _footprint() {
  if (!Platform.isIOS && !Platform.isMacOS) return (0, 0);
  final lib = DynamicLibrary.process();
  final malloc = lib.lookupFunction<Pointer<Uint8> Function(IntPtr), Pointer<Uint8> Function(int)>('malloc');
  final free = lib.lookupFunction<Void Function(Pointer<Uint8>), void Function(Pointer<Uint8>)>('free');
  final rusage = lib.lookupFunction<Int32 Function(Int32, Int32, Pointer<Uint8>), int Function(int, int, Pointer<Uint8>)>('proc_pid_rusage');
  final buf = malloc(512);
  try {
    if (rusage(pid, 4, buf) != 0) return (0, 0);
    final words = buf.cast<Uint64>();
    return (words[(16 + 7 * 8) ~/ 8], words[(16 + 28 * 8) ~/ 8]);
  } finally {
    free(buf);
  }
