class BigTarget extends CustomPainter {
  BigTarget(this.w, this.h);
  final int w, h;
  static ui.Image? _image;

  ui.Image _make() {
    final dpr = ui.PlatformDispatcher.instance.views.first.devicePixelRatio;
    final lw = w / dpr, lh = h / dpr;
    final recorder = ui.PictureRecorder();
    final canvas = Canvas(recorder)
      ..drawRect(
        Rect.fromLTWH(0, 0, lw, lh),
        Paint()
          ..shader = ui.Gradient.linear(Offset.zero, Offset(lw, lh), [
            const Color(0xFF203040),
            const Color(0xFF405060),
          ]),
