    for (var i = 0; i < 4; i++) {
      canvas.drawRect(Rect.fromLTWH(i * lw / 4 + 10, 10, lw / 8, lh / 2), Paint()..color = Colors.primaries[i]);
    }
    final picture = recorder.endRecording();
    // Drawn into the target at the device's pixel ratio.
    final cull = Rect.fromLTWH(0, 0, w.toDouble(), h.toDouble());
    final scaledRecorder = ui.PictureRecorder();
    Canvas(scaledRecorder, cull)
      ..clipRect(cull)
      ..scale(dpr)
      ..drawPicture(picture);
    final scaled = scaledRecorder.endRecording();
    final image = scaled.toImageSync(w, h);
    scaled.dispose();
    picture.dispose();
    return image;
  }

  @override
  void paint(Canvas canvas, Size size) {
    final image = _image ??= _make();
    canvas.drawImageRect(
      image,
      Rect.fromLTWH(0, 0, w.toDouble(), h.toDouble()),
      Rect.fromLTWH(0, 0, size.width, size.width * h / w),
      Paint()..filterQuality = FilterQuality.low,
    );
  }

  @override
  bool shouldRepaint(BigTarget oldDelegate) => oldDelegate.w != w || oldDelegate.h != h;
}
