import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

String _hex(int v) => '0x${v.toRadixString(16)}';

void main() {
  WidgetsFlutterBinding.ensureInitialized();
  HardwareKeyboard.instance.addHandler((KeyEvent e) {
    final chars = e.character?.runes.map(_hex).join(',') ?? '-';
    stdout.writeln(
      'KEY ${e.runtimeType} physical=${_hex(e.physicalKey.usbHidUsage)} '
      '(${e.physicalKey.debugName}) logical=${_hex(e.logicalKey.keyId)} '
      '(${e.logicalKey.debugName}) char=$chars',
    );
    return false;
  });
  runApp(const ProbeApp());
}

class ProbeApp extends StatefulWidget {
  const ProbeApp({super.key});

  @override
  State<ProbeApp> createState() => _ProbeAppState();
}

class _ProbeAppState extends State<ProbeApp> {
  final TextEditingController _controller = TextEditingController(
    text: 'hello',
  );
  String _last = 'hello';

  @override
  void initState() {
    super.initState();
    stdout.writeln('TEXT "hello"');
    _controller.addListener(() {
      if (_controller.text != _last) {
        _last = _controller.text;
        stdout.writeln('TEXT "$_last"');
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        body: Center(
          child: CallbackShortcuts(
            bindings: <ShortcutActivator, VoidCallback>{
              const SingleActivator(LogicalKeyboardKey.escape): () =>
                  stdout.writeln('ESCAPE ACTION'),
            },
            child: SizedBox(
              width: 400,
              child: TextField(controller: _controller, autofocus: true),
            ),
          ),
        ),
      ),
    );
  }
}
