<details><summary>inject.c (XTest key injector)</summary>

```c
// Presses and releases each keycode given on the command line, by raw X
// keycode, through XTEST on $DISPLAY. Gives the largest mapped top-level
// window the input focus first (Xvfb runs no window manager).
// Build: gcc -O1 -o inject inject.c -lX11 -lXtst
#include <X11/Xlib.h>
#include <X11/extensions/XTest.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main(int argc, char** argv) {
  Display* dpy = XOpenDisplay(NULL);
  if (dpy == NULL) {
    fprintf(stderr, "inject: no display\n");
    return 1;
  }
  Window root = DefaultRootWindow(dpy);
  Window root_ret, parent_ret, *children = NULL;
  unsigned int n = 0;
  Window best = None;
  long best_area = 0;
  if (XQueryTree(dpy, root, &root_ret, &parent_ret, &children, &n)) {
    for (unsigned int i = 0; i < n; i++) {
      XWindowAttributes a;
      if (XGetWindowAttributes(dpy, children[i], &a) &&
          a.map_state == IsViewable && (long)a.width * a.height > best_area) {
        best = children[i];
        best_area = (long)a.width * a.height;
      }
    }
    XFree(children);
  }
  if (best != None) {
    XSetInputFocus(dpy, best, RevertToParent, CurrentTime);
    XTestFakeMotionEvent(dpy, -1, 100, 100, CurrentTime);
    XSync(dpy, False);
    printf("inject: focused window 0x%lx\n", best);
  } else {
    printf("inject: no viewable window\n");
  }
  usleep(500000);
  for (int i = 1; i < argc; i++) {
    unsigned int keycode = (unsigned int)atoi(argv[i]);
    XTestFakeKeyEvent(dpy, keycode, True, CurrentTime);
    XSync(dpy, False);
    usleep(80000);
    XTestFakeKeyEvent(dpy, keycode, False, CurrentTime);
    XSync(dpy, False);
    printf("inject: keycode %u\n", keycode);
    fflush(stdout);
    usleep(400000);
  }
  XCloseDisplay(dpy);
  return 0;
}
